import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import {
  Input,
  LeaveConfirmModal,
  SearchInput,
  Select,
  dispatchAppToast,
  useDirtyTracking,
  useLeaveConfirm,
} from '@linm-soft-org/linm-web-common-components';
import { DocumentFormHeader } from '../../../components/layout';
import { createMaterialSearchConfig } from '../../../components/search';
import type { MaterialDto } from '../../../services/master/models';
import {
  createSalesPlan,
  getSalesPlan,
  updateSalesPlan,
  type SalesPlanDetail,
  type SalesPlanWriteBody,
} from '../../../services/salesPlans/endpoint';
import { useAppDispatch } from '../../../store/hooks';
import df from '../../../styles/documentForm.module.css';

type HeaderForm = {
  maPost: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  thang: string;
  nam: string;
  ngayKh1: string;
  ngayKh2: string;
  maKh: string;
  maBpH: string;
  maHsH: string;
  ongBa: string;
  diaChi: string;
  dienGiai: string;
  maNt: string;
  tyGia: string;
};

type LineForm = {
  maVt: string;
  tenVt: string;
  dvt: string;
  ton13: string;
  soLuong: string;
  giaNt2: string;
  tienNt2: string;
  maKxI: string;
};

function todayLocal(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}

function emptyHeader(): HeaderForm {
  const today = todayLocal();
  return {
    maPost: '3',
    ngayCt: today,
    ngayLct: today,
    soCt: '',
    thang: '',
    nam: '',
    ngayKh1: '',
    ngayKh2: '',
    maKh: '',
    maBpH: '',
    maHsH: '',
    ongBa: '',
    diaChi: '',
    dienGiai: '',
    maNt: '',
    tyGia: '',
  };
}

function emptyLine(): LineForm {
  return { maVt: '', tenVt: '', dvt: '', ton13: '', soLuong: '', giaNt2: '', tienNt2: '', maKxI: '' };
}

function dateText(value: string | null | undefined): string {
  if (!value) return '';
  return value.slice(0, 10);
}

function num(value: string): number {
  const text = value.trim();
  if (!text) return 0;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : 0;
}

function filled(value: string): boolean {
  const text = value.trim();
  if (!text) return false;
  return Number.isFinite(Number(text));
}

function round4(value: number): number {
  return Math.round(value * 10000) / 10000;
}

function showMoney(value: number): string {
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 4 }).format(value);
}

function fitsNumeric(value: string, digits: number): boolean {
  const text = value.trim();
  if (!/^-?\d+$/.test(text)) return false;
  const parsed = Number(text);
  return Number.isInteger(parsed) && Math.abs(parsed) < 10 ** digits;
}

function nullText(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}

function nullNumber(value: string): number | null {
  const text = value.trim();
  if (!text) return null;
  const parsed = Number(text);
  return Number.isFinite(parsed) ? parsed : null;
}

function nullInt(value: string): number | null {
  const text = value.trim();
  if (!text) return null;
  return Number(text);
}

function lineGia2(line: LineForm, tyGia: string): number {
  if (!filled(line.giaNt2) || !filled(tyGia)) return 0;
  return round4(num(line.giaNt2) * num(tyGia));
}

function lineTien2(line: LineForm, tyGia: string): number {
  if (!filled(line.tienNt2) || !filled(tyGia)) return 0;
  return round4(num(line.tienNt2) * num(tyGia));
}

function headerFromDetail(data: SalesPlanDetail): HeaderForm {
  return {
    maPost: data.maPost === '9' ? '9' : '3',
    ngayCt: dateText(data.ngayCt),
    ngayLct: dateText(data.ngayLct),
    soCt: data.soCt ?? '',
    thang: data.thang == null ? '' : String(data.thang),
    nam: data.nam == null ? '' : String(data.nam),
    ngayKh1: dateText(data.ngayKh1),
    ngayKh2: dateText(data.ngayKh2),
    maKh: data.maKh ?? '',
    maBpH: data.maBpH ?? '',
    maHsH: data.maHsH ?? '',
    ongBa: data.ongBa ?? '',
    diaChi: data.diaChi ?? '',
    dienGiai: data.dienGiai ?? '',
    maNt: data.maNt ?? '',
    tyGia: data.tyGia == null ? '' : String(data.tyGia),
  };
}

function lineFromDetail(line: SalesPlanDetail['lines'][number]): LineForm {
  return {
    maVt: line.maVt ?? '',
    tenVt: line.tenVt ?? '',
    dvt: line.dvt ?? '',
    ton13: line.ton13 == null ? '' : String(line.ton13),
    soLuong: line.soLuong == null ? '' : String(line.soLuong),
    giaNt2: line.giaNt2 == null ? '' : String(line.giaNt2),
    tienNt2: line.tienNt2 == null ? '' : String(line.tienNt2),
    maKxI: line.maKxI ?? '',
  };
}

function toBody(header: HeaderForm, lines: LineForm[]): SalesPlanWriteBody {
  return {
    maGd: '2',
    maPost: header.maPost === '9' ? '9' : '3',
    maCt: 'KH4',
    ngayCt: nullText(header.ngayCt),
    ngayLct: nullText(header.ngayLct),
    soCt: nullText(header.soCt),
    thang: nullInt(header.thang),
    nam: nullInt(header.nam),
    ngayKh1: nullText(header.ngayKh1),
    ngayKh2: nullText(header.ngayKh2),
    maKh: nullText(header.maKh),
    maBpH: nullText(header.maBpH),
    maHsH: nullText(header.maHsH),
    ongBa: nullText(header.ongBa),
    diaChi: nullText(header.diaChi),
    dienGiai: nullText(header.dienGiai),
    maNt: nullText(header.maNt),
    tyGia: nullNumber(header.tyGia),
    lines: lines.map(line => ({
      maVt: nullText(line.maVt),
      tenVt: nullText(line.tenVt),
      dvt: nullText(line.dvt),
      ton13: nullNumber(line.ton13),
      soLuong: nullNumber(line.soLuong),
      giaNt2: nullNumber(line.giaNt2),
      tienNt2: nullNumber(line.tienNt2),
      gia2: lineGia2(line, header.tyGia),
      tien2: lineTien2(line, header.tyGia),
      maKxI: nullText(line.maKxI),
    })),
  };
}

const Kh4FormPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { sttRec } = useParams();
  const [searchParams] = useSearchParams();
  const copyFrom = searchParams.get('copyFrom') ?? '';
  const isView = searchParams.get('mode') === 'view';
  const isNew = !sttRec;
  const isReadOnly = isView;
  const materialSearch = useMemo(() => createMaterialSearchConfig(), []);

  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    message: 'Có thay đổi chưa được lưu. Đóng form sẽ mất dữ liệu đã nhập.',
  });
  const { markDirty, markClean } = useDirtyTracking(onDirtyChange);

  const [header, setHeader] = useState<HeaderForm>(emptyHeader);
  const [lines, setLines] = useState<LineForm[]>([]);
  const [loadError, setLoadError] = useState('');
  const [banner, setBanner] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const source = sttRec || copyFrom;
    if (!source) {
      setHeader(emptyHeader());
      setLines([]);
      setLoadError('');
      markClean();
      return () => { cancelled = true; };
    }
    getSalesPlan(source)
      .then(data => {
        if (cancelled) return;
        setHeader(headerFromDetail(data));
        setLines(data.lines.map(lineFromDetail));
        setLoadError('');
        markClean();
      })
      .catch(() => {
        if (!cancelled) setLoadError('Không tìm thấy kế hoạch bán hàng');
      });
    return () => { cancelled = true; };
  }, [sttRec, copyFrom]);

  const tSoLuong = round4(lines.reduce((sum, line) => sum + num(line.soLuong), 0));
  const tTienNt2 = round4(lines.reduce((sum, line) => sum + num(line.tienNt2), 0));
  const tTien2 = round4(lines.reduce((sum, line) => sum + lineTien2(line, header.tyGia), 0));
  const title = isView
    ? 'Xem kế hoạch bán hàng'
    : isNew
      ? 'Thêm kế hoạch bán hàng'
      : 'Sửa kế hoạch bán hàng';
  const hideBody = Boolean(loadError);

  const patchHeader = (patch: Partial<HeaderForm>) => {
    markDirty();
    setHeader(prev => ({ ...prev, ...patch }));
  };

  const patchLine = (index: number, patch: Partial<LineForm>) => {
    markDirty();
    setLines(prev => prev.map((line, i) => (i === index ? { ...line, ...patch } : line)));
  };

  const patchAmount = (index: number, field: 'soLuong' | 'giaNt2', value: string) => {
    markDirty();
    setLines(prev => prev.map((line, i) => {
      if (i !== index) return line;
      const next = { ...line, [field]: value };
      if (next.tienNt2.trim() !== '') return next;
      if (filled(next.soLuong) && filled(next.giaNt2)) {
        return { ...next, tienNt2: String(round4(num(next.soLuong) * num(next.giaNt2))) };
      }
      return next;
    }));
  };

  const save = async () => {
    if (header.ngayKh1 && header.ngayKh2 && header.ngayKh1 > header.ngayKh2) {
      setBanner('Ngày kế hoạch bắt đầu lớn hơn ngày kết thúc, kiểm tra lại');
      return;
    }
    if (header.thang.trim() && !fitsNumeric(header.thang, 2)) {
      setBanner('Tháng không đúng kiểu số (tối đa 2 chữ số)');
      return;
    }
    if (header.nam.trim() && !fitsNumeric(header.nam, 5)) {
      setBanner('Năm không đúng kiểu số (tối đa 5 chữ số)');
      return;
    }
    setBanner('');
    const body = toBody(header, lines);
    setSaving(true);
    try {
      if (sttRec && !isView) await updateSalesPlan(sttRec, body);
      else await createSalesPlan(body);
      markClean();
      dispatchAppToast(dispatch, { message: 'Đã lưu kế hoạch bán hàng', type: 'success' });
      navigate('/bh/kh4');
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: err instanceof Error ? err.message : 'Lưu thất bại',
        type: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={df.page} data-testid="ct-kh4-form">
      <DocumentFormHeader
        title={title}
        isNew={isNew}
        isReadOnly={isReadOnly}
        saving={saving}
        saveLabel="Lưu"
        saveEditLabel="Lưu"
        saveTestId="ct-kh4-save-btn"
        onBack={() => guardedNavigate(() => navigate('/bh/kh4'))}
        onSave={hideBody || isReadOnly ? undefined : save}
      />
      {(loadError || banner) ? <div className={df.errorBanner}>{loadError || banner}</div> : null}
      {!hideBody && (
        <>
          <section className={df.section}>
            <h2 className={df.sectionTitle}>Chứng từ</h2>
            <div className={df.row4}>
              <div className={df.field}>
                <label className={df.label}>Loại giao dịch</label>
                <Input data-testid="ct-kh4-field-maGd" readOnly value="2 — Lập kế hoạch bán hàng" />
              </div>
              <div className={df.field}>
                <label className={df.label}>Trạng thái</label>
                <Select
                  data-testid="ct-kh4-field-maPost"
                  disabled={isReadOnly}
                  value={header.maPost}
                  onChange={e => patchHeader({ maPost: e.target.value })}
                  options={[
                    { value: '3', label: 'Lập kế hoạch' },
                    { value: '9', label: 'Kế hoạch đã phê duyệt' },
                  ]}
                />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày chứng từ</label>
                <Input type="date" data-testid="ct-kh4-field-ngayCt" disabled={isReadOnly} value={header.ngayCt} onChange={e => patchHeader({ ngayCt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngày lập chứng từ</label>
                <Input type="date" data-testid="ct-kh4-field-ngayLct" disabled={isReadOnly} value={header.ngayLct} onChange={e => patchHeader({ ngayLct: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Số chứng từ</label>
                <Input data-testid="ct-kh4-field-soCt" disabled={isReadOnly} value={header.soCt} onChange={e => patchHeader({ soCt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Tháng</label>
                <Input inputMode="numeric" data-testid="ct-kh4-field-thang" disabled={isReadOnly} value={header.thang} onChange={e => patchHeader({ thang: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Năm</label>
                <Input inputMode="numeric" data-testid="ct-kh4-field-nam" disabled={isReadOnly} value={header.nam} onChange={e => patchHeader({ nam: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Kế hoạch từ ngày</label>
                <Input type="date" data-testid="ct-kh4-field-ngayKh1" disabled={isReadOnly} value={header.ngayKh1} onChange={e => patchHeader({ ngayKh1: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Kế hoạch đến ngày</label>
                <Input type="date" data-testid="ct-kh4-field-ngayKh2" disabled={isReadOnly} value={header.ngayKh2} onChange={e => patchHeader({ ngayKh2: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Đối tượng</label>
                <Input data-testid="ct-kh4-field-maKh" disabled={isReadOnly} value={header.maKh} onChange={e => patchHeader({ maKh: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Bộ phận</label>
                <Input data-testid="ct-kh4-field-maBpH" disabled={isReadOnly} value={header.maBpH} onChange={e => patchHeader({ maBpH: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Nhân sự</label>
                <Input data-testid="ct-kh4-field-maHsH" disabled={isReadOnly} value={header.maHsH} onChange={e => patchHeader({ maHsH: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Người giao dịch</label>
                <Input data-testid="ct-kh4-field-ongBa" disabled={isReadOnly} value={header.ongBa} onChange={e => patchHeader({ ongBa: e.target.value })} />
              </div>
              <div className={`${df.field} ${df.spanCol2}`}>
                <label className={df.label}>Địa chỉ</label>
                <Input maxLength={200} data-testid="ct-kh4-field-diaChi" disabled={isReadOnly} value={header.diaChi} onChange={e => patchHeader({ diaChi: e.target.value })} />
              </div>
              <div className={`${df.field} ${df.spanCol2}`}>
                <label className={df.label}>Diễn giải</label>
                <Input data-testid="ct-kh4-field-dienGiai" disabled={isReadOnly} value={header.dienGiai} onChange={e => patchHeader({ dienGiai: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Ngoại tệ</label>
                <Input data-testid="ct-kh4-field-maNt" disabled={isReadOnly} value={header.maNt} onChange={e => patchHeader({ maNt: e.target.value })} />
              </div>
              <div className={df.field}>
                <label className={df.label}>Tỷ giá</label>
                <Input inputMode="decimal" data-testid="ct-kh4-field-tyGia" disabled={isReadOnly} value={header.tyGia} onChange={e => patchHeader({ tyGia: e.target.value })} />
              </div>
            </div>
          </section>

          <section className={df.section}>
            <h2 className={df.sectionTitle}>Dòng kế hoạch</h2>
            {!isReadOnly && (
              <button
                type="button"
                className={df.btnAddLine}
                data-testid="ct-kh4-line-add-btn"
                onClick={() => {
                  markDirty();
                  setLines(prev => [...prev, emptyLine()]);
                }}
              >
                Thêm dòng
              </button>
            )}
            <div className={df.tableWrapper}>
              <table className={df.linesTable}>
                <thead>
                  <tr>
                    <th>Mã hàng</th>
                    <th>Tên hàng hóa</th>
                    <th>ĐVT</th>
                    <th>Tồn</th>
                    <th>Số lượng</th>
                    <th>Giá</th>
                    <th>Thành tiền</th>
                    <th>Giá VNĐ</th>
                    <th>Tiền VNĐ</th>
                    <th>Kiểu xe</th>
                    {!isReadOnly && <th />}
                  </tr>
                </thead>
                <tbody>
                  {lines.map((line, index) => (
                    <tr key={index}>
                      <td>
                        <SearchInput
                          config={materialSearch}
                          value={line.maVt}
                          primaryDisplay={line.maVt}
                          secondaryDisplay={line.tenVt}
                          disabled={isReadOnly}
                          showLabel={false}
                          data-testid={`ct-kh4-line-${index}-maVt`}
                          onChange={(item: MaterialDto) => patchLine(index, {
                            maVt: item.code,
                            tenVt: item.name ?? '',
                            dvt: item.unitCode ?? '',
                            ton13: '',
                          })}
                          onClear={() => patchLine(index, { maVt: '', tenVt: '', dvt: '', ton13: '' })}
                        />
                      </td>
                      <td data-testid={`ct-kh4-line-${index}-tenVt`}>{line.tenVt}</td>
                      <td data-testid={`ct-kh4-line-${index}-dvt`}>{line.dvt}</td>
                      <td data-testid={`ct-kh4-line-${index}-ton13`}>{line.ton13}</td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-kh4-line-${index}-soLuong`}
                          disabled={isReadOnly}
                          value={line.soLuong}
                          onChange={e => patchAmount(index, 'soLuong', e.target.value)}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-kh4-line-${index}-giaNt2`}
                          disabled={isReadOnly}
                          value={line.giaNt2}
                          onChange={e => patchAmount(index, 'giaNt2', e.target.value)}
                        />
                      </td>
                      <td>
                        <Input
                          inputMode="decimal"
                          data-testid={`ct-kh4-line-${index}-tienNt2`}
                          disabled={isReadOnly}
                          value={line.tienNt2}
                          onChange={e => patchLine(index, { tienNt2: e.target.value })}
                        />
                      </td>
                      <td data-testid={`ct-kh4-line-${index}-gia2`}>{showMoney(lineGia2(line, header.tyGia))}</td>
                      <td data-testid={`ct-kh4-line-${index}-tien2`}>{showMoney(lineTien2(line, header.tyGia))}</td>
                      <td>
                        <Input
                          data-testid={`ct-kh4-line-${index}-maKxI`}
                          disabled={isReadOnly}
                          value={line.maKxI}
                          onChange={e => patchLine(index, { maKxI: e.target.value })}
                        />
                      </td>
                      {!isReadOnly && (
                        <td>
                          <button
                            type="button"
                            className={df.btnDeleteLine}
                            data-testid={`ct-kh4-line-remove-btn-${index}`}
                            onClick={() => {
                              markDirty();
                              setLines(prev => prev.filter((_, i) => i !== index));
                            }}
                          >
                            ×
                          </button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <div className={df.footer}>
            <div className={df.totalBlock} data-testid="ct-kh4-field-tSoLuong">
              <span className={df.totalLabel}>Tổng số lượng</span>
              <span>{showMoney(tSoLuong)}</span>
            </div>
            <div className={df.totalBlock} data-testid="ct-kh4-field-tTienNt2">
              <span className={df.totalLabel}>Tổng thành tiền bán</span>
              <span>{showMoney(tTienNt2)}</span>
            </div>
            <div className={df.totalBlock} data-testid="ct-kh4-field-tTien2">
              <span className={df.totalLabel}>Tổng tiền VNĐ bán</span>
              <span>{showMoney(tTien2)}</span>
            </div>
          </div>
        </>
      )}
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default Kh4FormPage;
